import{experimentResult,ivCurrent}from './el1-models.js?v=20261023-physicscomplete01';
const ink='#faf5ed',mint='#aacac1',coral='#e9b299',dim='#9fbac2';const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const fmt=x=>Number(Number(x).toFixed(3));const T=(x,y,s,n=17,c=ink)=>`<text x="${x}" y="${y}" text-anchor="middle" fill="${c}" font-family="sans-serif" font-size="${n}">${esc(s)}</text>`;const L=(x,y,u,v,c=dim,w=3)=>`<path d="M${x} ${y}L${u} ${v}" stroke="${c}" stroke-width="${w}" fill="none"/>`;const dot=(x,y,r=5,c=coral)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}"/>`;const B=(x,y,w,h,c='#1e3c4c')=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="10" fill="${c}" stroke="${dim}"/>`;
export const symbolNames={cell:'Cell',battery:'Battery',switch:'Open switch',closed:'Closed switch',lamp:'Lamp',fuse:'Fuse',resistor:'Fixed resistor',variable:'Variable resistor',ammeter:'Ammeter',voltmeter:'Voltmeter',diode:'Diode',led:'LED',thermistor:'Thermistor',ldr:'LDR'};
const descriptions={cell:'One long and one short parallel line',battery:'Two long/short line pairs',switch:'Two contacts with a gap and a raised lever',closed:'Two contacts joined by a lever',lamp:'A circle with a cross',fuse:'A narrow rectangle with a continuous line through its centre',resistor:'A rectangle in the conducting line',variable:'A resistor rectangle crossed by a diagonal arrow',ammeter:'A circle containing the letter A',voltmeter:'A circle containing the letter V',diode:'A triangle pointing at a bar, inside a circle',led:'A diode inside a circle with two arrows pointing outward',thermistor:'A resistor rectangle crossed by a diagonal line with a short bent tail',ldr:'A resistor inside a circle, with two arrows pointing inward'};
export const electricSVG=(body,label)=>`<svg viewBox="0 0 560 460" role="img" aria-label="${esc(label)}">${body}</svg>`;
export function symbolGlyph(k,x=280,y=200,scale=1){let a='',wire=L(-58,0,-32,0)+L(32,0,58,0),circle=`<circle r="30" fill="#1a3545" stroke="${ink}" stroke-width="2.5"/>`;if(k==='cell'||k==='battery'){a=L(-58,0,-12,0)+L(k==='battery'?30:12,0,58,0)+L(-12,-29,-12,29,ink)+L(4,-16,4,16,ink);if(k==='battery')a+=L(4,0,18,0)+L(18,-29,18,29,ink)+L(30,-16,30,16,ink);}
else if(k==='switch'||k==='closed')a=wire+`<circle cx="-30" r="4" fill="#1a3545" stroke="${ink}"/><circle cx="30" r="4" fill="#1a3545" stroke="${ink}"/>`+L(-27,0,27,k==='switch'?-24:0,ink);
else if(['lamp','ammeter','voltmeter'].includes(k))a=wire+circle+(k==='lamp'?L(-20,-20,20,20,ink)+L(-20,20,20,-20,ink):T(0,8,k==='ammeter'?'A':'V',25));
else if(k==='diode'||k==='led'){a=wire+circle+`<path d="M-19 -18L13 0L-19 18Z" fill="none" stroke="${ink}" stroke-width="2.5"/>`+L(13,-22,13,22,ink)+L(-30,0,-19,0)+L(13,0,30,0);if(k==='led')a+=L(20,-24,41,-45,ink,2)+L(32,-15,53,-36,ink,2)+`<path d="M35 -45h6v6M47 -36h6v6" fill="none" stroke="${ink}"/>`;}
else {a=wire+`<rect x="-32" y="${k==='fuse'?-10:-17}" width="64" height="${k==='fuse'?20:34}" fill="#1a3545" stroke="${ink}" stroke-width="2.5"/>`;if(k==='fuse')a+=L(-32,0,32,0,ink);if(k==='variable')a+=L(-43,32,43,-32,ink)+`<path d="M33 -32h10v10" fill="none" stroke="${ink}" stroke-width="3"/>`;if(k==='thermistor')a+=`<path d="M-32 28h18l36 -56" stroke="${ink}" fill="none" stroke-width="2.5"/>`;if(k==='ldr')a=`<circle r="39" fill="none" stroke="${ink}" stroke-width="2"/>`+a+L(-50,-61,-23,-33,ink,2)+L(-34,-72,-7,-44,ink,2)+`<path d="M-23 -42v9h-9M-7 -53v9h-9" fill="none" stroke="${ink}"/>`;}
return`<g transform="translate(${x} ${y}) scale(${scale})">${a}</g>`;}
export function symbolAssessment(f){let k=f.symbol;return electricSVG(symbolGlyph(k,280,205,2)+T(280,385,'Identify the standard circuit symbol',21),descriptions[k]+'. Identify the component.');}
export function symbolGallery(state='0'){let sets=[['cell','battery','switch','closed','lamp','fuse','resistor'],['variable','ammeter','voltmeter','diode','led','thermistor','ldr']],keys=sets[state==='2'?'1':'0'],body=T(280,32,'Standard symbols · read the connections',22);for(let[i,k]of keys.entries()){let x=i%2?405:150,y=105+Math.floor(i/2)*98;body+=symbolGlyph(k,x,y,.7)+T(x,y+37,symbolNames[k],16);}return electricSVG(body,keys.map(k=>symbolNames[k]+': '+descriptions[k]).join('. '));}
const pts=[[265,115],[90,115],[90,315],[470,315],[470,115],[295,115]];function marker(p){let lengths=[175,200,380,200,175],d=((p%1)+1)%1*1130;for(let i=0;i<lengths.length;i++){if(d<=lengths[i]){let f=d/lengths[i];return{ x:pts[i][0]+f*(pts[i+1][0]-pts[i][0]),y:pts[i][1]+f*(pts[i+1][1]-pts[i][1])};}d-=lengths[i];}return{x:265,y:115};}
export function circuitFigure({component='resistor',closed=true,V=2,R=10,I=V/R,progress=0,moving=false,wiring='correct',caption=''}={}){let a=T(280,28,caption||'Read current through · potential difference across',21)+`<path d="M265 115H90V315H220M340 315H470V115H430M390 115H295" fill="none" stroke="${mint}" stroke-width="4"/>`+symbolGlyph('cell',280,115,.65)+symbolGlyph(closed?'closed':'switch',410,115,.35)+symbolGlyph(component,280,315,1)+`<circle cx="90" cy="225" r="19" fill="#1a3545" stroke="${ink}" stroke-width="2"/>`+T(90,232,wiring==='wrong'?'V':'A',21)+`<path d="M220 315V398H247M313 398H340V315" stroke="${dim}" fill="none" stroke-width="2.5"/>`+symbolGlyph(wiring==='wrong'?'ammeter':'voltmeter',280,398,.55)+T(280,82,V+' V',20)+T(280,275,wiring==='wrong'?'Incorrect placement: no valid current prediction':(closed?fmt(I):0)+' A throughout the single loop',18)+T(280,355,component==='resistor'?'R = '+R+' Ω':'Lamp / conceptual load',16)+T(280,448,wiring==='wrong'?'Wrong: meters exchanged — do not record this setup':'Conventional direction + → − externally · tracer speed symbolic',13);
if(moving&&closed&&wiring==='correct')for(let j=0;j<10;j++){let q=marker(progress+j/10);a+=dot(q.x,q.y,4,'#ffdbc2');}return electricSVG(a,`Low-voltage conceptual circuit, ${component}, ${closed?'closed':'open'} switch, ${V}V. ${wiring==='wrong'?'Invalid measuring setup; no current prediction.':(closed?fmt(I):0)+'A single-loop current.'} ${wiring==='wrong'?'Incorrect: ammeter across component, voltmeter in series.':'Correct: ammeter in series, voltmeter across component.'} Tracers indicate conventional current, not electrons or energy packets.`);}
export function chargeFigure({a='0.5',b='8',progress=1,movie=false}={}){let r=experimentResult('current',a,b),t=r.t*progress,Q=r.I*t,body=T(280,30,'Count charge passing one cross-section',23)+B(65,120,430,120,'#25495a')+L(280,95,280,270,coral,3)+T(280,86,'Reference section',16)+T(280,306,r.I+' A ×'+fmt(t)+' s',22)+T(280,347,'Q = '+fmt(Q)+' C passed',26)+T(280,395,'Same current before and after the component',17)+T(280,438,'Markers show conventional current · not literal electron drift or particle counts',12);for(let j=0;j<14;j++){let x=75+((j/14+progress)%1)*410,y=155+(j%2)*45;body+=dot(x,y,7,mint);}return electricSVG(body,`Charge flow: current${r.I}A for${fmt(t)}s gives cumulative${fmt(Q)}C past the reference section. Markers move in conventional direction; no charge is created or used up. Playback is a normalised worked time example.`);}
export function wireFigure({a='0.25',b='1',progress=1,revealed=true}={}){let r=experimentResult('wire',a,b),len=r.L*600,rad=6*r.A,body=T(280,30,'Measure the selected length and both readings',22)+`<rect x="80" y="${200-rad}" width="${len}" height="${rad*2}" rx="${rad}" fill="#c99c79" stroke="#eed3b2"/><ellipse cx="${80+len}" cy="200" rx="5" ry="${rad}" fill="#8e6753"/>`+L(80,240,80+len,240)+L(80,230,80,250)+L(80+len,230,80+len,250)+T(80+len/2,275,r.L+' m',21)+T(280,100,'Same material · fixed temperature ·1 V',19)+T(280,325,'Measured current '+fmt(r.I)+' A',22)+T(280,365,revealed?'R = V/I = '+fmt(r.R)+' Ω':'Use measured V/I to predict R',23)+T(280,410,'Cross-section index '+r.A+' · original coefficient',16)+T(280,442,'Geometry exaggerated · readings are ideal virtual data, not real wire ratings',12);for(let j=0;j<5;j++)body+=dot(80+((progress+j/5)%1)*len,200,3,mint);return electricSVG(body,`Selected wire length${r.L}m cross-section index${r.A}, fixed material/temperature; measured1V and${r.I}A. R${r.R}ohms. Original R=2L/A toy rule; not a required equation or calibrated material.`);}
const colours={resistor:mint,lamp:coral,diode:'#a8bedb'};export function ivFigure({a='resistor',b='2',progress=1,movie=false}={}){let V=movie?-4+8*progress:Number(b),k=a,I=ivCurrent(k,V),x=v=>280+v*49,y=i=>260-i*155,body=T(280,28,'Current vertically · potential difference horizontally',21)+L(65,260,505,260)+L(280,390,280,65)+T(280,435,'Potential difference / V',17)+T(300,59,'I / A',17);for(let v of[-4,-2,2,4])body+=T(x(v),281,v,13);for(let i of[-.5,.5,1])body+=T(259,y(i)+5,i,13);let keys=movie?['resistor','lamp','diode']:[k];for(let key of keys){let d='';for(let n=0;n<=80;n++){let v=-4+n/10;d+=(n?'L':'M')+x(v)+' '+y(ivCurrent(key,v));}body+=`<path d="${d}" fill="none" stroke="${colours[key]}" stroke-width="3"/>`;}body+=dot(x(V),y(I),7,colours[k])+T(280,320,k+' · '+fmt(V)+' V · '+fmt(I)+' A',20)+T(280,356,I===0?'Toy reverse current0: no finite V/I value':'Point resistance V/I = '+fmt(V/I)+' Ω',18)+T(280,394,'Mint: resistor · coral: lamp · blue: diode',14)+T(280,453,'Original illustrative curves · not device ratings or carrier motion',12);return electricSVG(body,`I–V graph with V horizontal and I vertical. ${k} point${fmt(V)}V, ${fmt(I)}A. ${I===0?'Toy current zero; do not divide by zero.':'Point resistance'+fmt(V/I)+'ohms.'} Ohmic straight line at constant temperature, filament curve with growing resistance, diode very-high reverse resistance represented by zero. Not real ratings.`);}
export function electricFigure(o={}){let k=(o.kind||'symbols').replace(/-(model|data)$/,'');if(k==='symbols'&&o.quiz)return symbolAssessment({symbol:o.state});if(o.concealed)return electricSVG(T(280,220,'Predict, then reveal the evidence',23),'Evidence concealed until prediction');if(k==='symbols'){if(o.kind?.endsWith('-model')){let r=experimentResult(k,o.a||'lamp',o.b||'closed');return circuitFigure({component:r.component,closed:r.closed,V:6,R:r.component==='lamp'?10:20,wiring:o.wiring||'wrong',caption:'Choose and check the measuring circuit'});}return ['3','4'].includes(o.state)?circuitFigure({caption:'Ammeter in series · voltmeter across component'}):symbolGallery(o.state);}
if(k==='current')return chargeFigure(o);if(k==='wire')return wireFigure(o);if(k==='iv')return ivFigure(o);let r=experimentResult('ohm',o.a||'2',o.b||'10');return circuitFigure({...r,moving:!!o.movie,progress:o.progress||0,caption:'V = IR · change voltage or resistance'});}
